    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit strategy)
    let mut score = post_res;

    // Penalty for "slivers": if post_residual is small but > 0, it's often wasted space.
    // We penalize values < 10 exponentially.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res).powf(1.5) * 5.0;
    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, penalize bins that leave a residual smaller than next_item_size.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_res) * 2.5;
        }
    }

    // Stream progression weight:
    // As we approach the end of the stream, prioritize tightly packed bins (low post_residual)
    // more aggressively to avoid opening new bins.
    score += (post_res * progress * 2.0);

    // If this is the only fitting bin, give it a massive priority bonus to prevent
    // unnecessary new bin creation unless the fit is truly abysmal.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Global bin management:
    // If we are opening a new bin (bin_residual == bin_capacity), apply a heavy cost
    // that decays as the stream progresses, but is always higher than a decent fit.
    if bin_residual == bin_capacity {
        score = 40.0 + (1.0 - progress) * 30.0;
    }

    // Apply mean residual correction:
    // Avoid creating bins that are significantly "emptier" than the current average.
    if post_residual as f64 > mean_residual {
        score += (post_res - mean_residual) * 0.5;
    }

    score
}

