    // Harmonic/Modulo logic: favor residuals that are multiples of common item sizes (e.g., 20, 25).
    // This maximizes the probability of fitting future items by keeping bin space "round".
    let remainder_mod = (post_residual % 20) as f64;
    score += remainder_mod * 0.5;

    // Global state awareness: if we are near the end of the stream, prioritize space density.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
