    // 3. Global state awareness:
    // If we are at the end of the stream, prioritize filling existing bins to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Balance bin usage:
    // Penalize opening a new bin (where bin_residual == bin_capacity) unless the fit is truly poor.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If we have many bins already, make opening a new one very expensive.
        score += open_bins_count as f64 * 1.5;
    }

    // 5. Mean residual alignment:
    // Avoid creating bins that are significantly "emptier" than the average bin.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // 6. Last chance logic:
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
