    };

    // Deviation from mean: avoid bins that are much emptier than the average open bin
    // to keep the packing density uniform.
    let density_penalty = (post - mean_residual).abs() * 0.5;

    let score = waste_penalty + open_bin_penalty + lookahead_mod + density_penalty;

