    let lookahead_penalty = if next_item_size > post_residual && post_residual < 40 {
        (next_item_size as f64 - post_res_f) * 0.5
    } else {
        0.0
    };

    // Dynamic thresholding: As we reach the end of the stream, prioritize closing bins (lower mean_residual).
    // We penalize opening new bins by increasing the base score as open_bins_count grows.
    let new_bin_cost = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 2.0) + (progress * 50.0)
