    };

    // Coupling: Use non-linear polynomial relationship between post_residual and progress.
    // Near the end of the stream, we want to be more aggressive with packing (tighter fits).
    let progress_scaling = 1.0 + (progress * progress);

    let mut score = (post_res_f * progress_scaling) + dead_space_penalty + lookahead_penalty + new_bin_cost;

    // Favor bins that have residuals closer to the global mean to maintain bin uniformity.
    let uniformity_penalty = (post_res_f - mean_residual).abs() * 0.2;
    score += uniformity_penalty;

