    // Targets "Perfect Fit" windows while penalizing fragments that cannot fit typical items (10-80).

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize remnants that are too small to be useful (1-9 range)
    // Small remnants are "dead weight" unless they are 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Coupling: Reward bins that can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward placement that keeps the bin viable for the next item
            score -= 15.0;
        } else {
            // Penalize if this placement blocks the next item from fitting here
            score += 10.0;
        }
    }

    // 3. Density Balancing: Avoid opening new bins unless necessary
    // Only consider a new bin if the mean residual of current bins is already very low
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // Penalize opening a new bin if we have plenty of open space elsewhere
            score += 40.0;
        } else {
            // Otherwise, keep the cost of a new bin neutral to allow it if needed
            score += 5.0;
        }
    }

    // 4. Fitting Pressure: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression weighting: As we approach the end of the stream, 
    // prioritize tight packing (minimizing post_residual) to close bins.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;
    let post = post_residual as f64;

    // Base score: Non-linear penalty for residual space to encourage tight packing.
    // Exponential growth forces better utilization of existing bins.
    let mut score = post.powf(2.2);

    if is_new_bin {
        // Dynamic barrier: opening a new bin is expensive, but the cost decays
        // as the packing sequence progresses to allow for final cleanup.
        let base_new_bin_cost = 4200.0 - (progress * 1500.0);
        let open_bin_penalty = (open_bins_count as f64).powf(0.8) * 280.0;

        // Lookahead: if the next item is large, avoid opening a new bin if possible.
        let lookahead_block = if next_item_size > (bin_capacity / 2) { 1800.0 } else { 0.0 };

        score = base_new_bin_cost + open_bin_penalty + lookahead_block;
    } else {
        // Reward perfect fits heavily, scaling with progress to prioritize completion.
        if post_residual == 0 {
            score -= 7500.0 + (progress * 2500.0);
        }

        // Penalty for "fragmentation traps": residuals that are too small to be useful
        // but large enough to waste capacity, especially if a next item is pending.
        if post_residual > 0 && post_residual < 15 {
            score += 2800.0 * (1.0 - progress * 0.3);
        }

        // Lookahead efficiency: Reward bins that can accommodate the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 2200.0 * (1.0 + progress * 0.2);
                if post_residual == next_item_size {
                    score -= 2000.0; // Perfect lookahead fit
                }
            } else {
                // Penalize bins that cannot fit the next item if they are the only option.
                if fitting_bins_count == 1 {
                    score += 1200.0;
                }
            }
        }

        // Density pressure: Prefer bins that stay below the mean_residual
        // to keep the bin distribution uniform and prevent early closure.
        if post < mean_residual {
            score -= (mean_residual - post) * 45.0;
        } else {
            score += (post - mean_residual) * 20.0;
        }

        // Emergency valve: If only one bin fits, prioritize it strongly to prevent premature new bin opening.
        if fitting_bins_count == 1 {
            score -= 9000.0;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear residual penalty focusing on cubic growth to penalize large gaps more severely
    let mut score = post.powf(2.45);

    if is_new_bin {
        // Dynamic base cost: reduce threshold as we approach the end to avoid creating new bins
        // Increased base cost slightly to discourage opening new bins unless necessary
        let base_cost = 4150.0 - (progress * 1400.0);
        let scale_factor = (open_bins_count as f64).powf(0.92) * 395.0;

        // Lookahead pressure: bias towards existing bins if next item is small
        let lookahead_pressure = if next_item_size > 0 && (next_item_size as f64) < (mean_residual * 1.8) {
            3100.0
        } else {
            1900.0
        };
        score = base_cost + scale_factor + lookahead_pressure;
    } else {
        // Reward perfect fits with higher weight to encourage filling existing bins
        if post_residual == 0 {
            score -= 9800.0 + (progress * 4800.0);
        } else if post_residual < (bin_capacity / 20) {
            score -= 6200.0;
        }

        // Refined blocking penalty: account for scarcity of fitting bins
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let scarcity_penalty = if fitting_bins_count <= 2 { 9200.0 } else { 2900.0 };
            score += scarcity_penalty * (1.0 + progress.powf(0.5));
        }

        // Targeted residual control: force tighter packing based on mean_residual
        let target_residual = mean_residual * (0.45 + (progress * 0.35));
        let deviation = (target_residual - post).abs();
        score -= (deviation * 14.0) / (1.0 + (post / cap).sqrt());

        // Aggressive bin closure: force use of bins with low space when options are few
        if fitting_bins_count <= 2 {
            score -= 26000.0 * (1.0 - progress * 0.12);
        }

        // Density pressure: penalize remaining space to force tight packing
        score += post * (0.95 + progress.powf(1.1)) * 520.0;

        // Dead space penalty: focus on small gaps that prevent future fits
        if post_residual < (bin_capacity / 12) && post_residual > 0 {
            score += 4800.0 * (1.0 - progress * 0.2);
        }

        // Lookahead optimization: prioritize bins that can swallow the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 3200.0 * (1.0 + progress * 0.4);
                if (post_residual - next_item_size) == 0 {
                    score -= 3600.0;
                }
            } else {
                score += 3800.0;
            }
        }

        // Entropy adjustment: minimize variance in residual space
        let entropy_penalty = (post - mean_residual).abs() * (1.5 - progress);
        score += entropy_penalty * 1600.0;

        // High density reward: prioritize closing bins that are nearly full
        if post < (cap * 0.15) && post > 0.0 {
            score -= 2800.0 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit future items.
    // If post_residual is in (0, 10), it is likely "dead space" because min item size is ~10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by the current number of open bins to avoid fragmentation.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Coupling: Reward placements that accommodate the next item.
    // If the next item fits in the post_residual, drastically reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item,
    // prioritize it to avoid creating unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: If the current bin is very empty compared to the mean,
    // favor filling it to bring it closer to the average utilization.
    if (bin_capacity - bin_residual) < (bin_capacity as f64 - mean_residual) as u32 {
        score -= 5.0;
    }

    score
}

