pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual.
    // Penalty for creating 'dead space' that is too small for any future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // 2. Lookahead optimization: If next_item_size exists, penalize bins that cannot fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        } else {
            // Reward bins that can accommodate the next item perfectly.
            score -= 10.0 * (1.0 - progress);
        }
    }

    // 3. Global state management: Avoid opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many 
    // bins are already open and how much space is currently wasted.
    if bin_residual == bin_capacity {
        score += 40.0;
        score += (open_bins_count as f64) * 2.0;
        score += (100.0 - mean_residual) * 0.5;
    }

    // 4. Critical thresholding: If only one bin can fit the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Dynamic horizon: As the stream nears the end, become more aggressive 
    // about filling bins to reduce the final bin count.
    if progress > 0.8 {
        score -= (100 - post_residual) as f64 * 0.2;
    }

    score
}

