        let base_new_bin_cost = 3800.0 - (progress * 1400.0);
        let volume_pressure = (open_bins_count as f64).powf(0.8) * 280.0;

        // Only open new if we cannot accommodate the next_item_size effectively
        let lookahead_block = if next_item_size > 0 && (next_item_size as f64) > (mean_residual * 0.8) {
            1200.0
        } else {
            0.0
        };
        score = base_new_bin_cost + volume_pressure + lookahead_block;
    } else {
        // 1. Reward perfect fits aggressively
        if post_residual == 0 {
            score -= 7200.0 + (progress * 2500.0);
        } else if post_residual < (bin_capacity / 20) {
            score -= 3200.0;
        }

        // 2. Scarcity/Constraint Handling
