        if fitting_bins_count == 1 {
            score -= 8500.0;
        }

        // 3. Lookahead Logic: Reward placement that leaves room for the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 2200.0 * (1.0 + progress * 0.2);
                // Bonus for "tight" lookahead fit
                if (post_residual - next_item_size) < (bin_capacity / 15) {
