pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that are too small to be useful
    // (e.g., < 10) but too large to be zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual == 0 {
        score -= 20.0; // Reward perfect fits strongly
    }

    // 2. Open Bins Pressure: Penalize opening a new bin if we have many already,
    // unless the fit is excellent.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // If we have many open bins, penalize opening a new one significantly
        if open_bins_count > 5 {
            score += 40.0;
        }
    }

    // 3. Lookahead coupling: If next_item_size exists, favor bins that leave space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can accommodate the next item
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // Penalize bins that block the next item from fitting here
        }
    }

    // 4. Fitting Bins Count: If this is the last chance to fit the item in an existing bin,
    // be conservative about opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0; // Strongly prefer the last available fitting bin over a new one
    }

    // 5. Progression adjustment: As we approach the end of the stream, prioritize closing gaps.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 * 0.2);

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Shift exponent to penalize large gaps more aggressively in mid-game
    let mut score = post.powf(2.35 + (progress * 0.2));

    if is_new_bin {
        // Dynamic barrier: increase cost of opening new bins as more bins are already active
        // Use a non-linear scaling for open_bins_count to prevent excessive fragmentation
        let base_cost = 3950.0 - (progress * 1100.0);
        let scale_factor = (open_bins_count as f64).powf(1.05) * 420.0;

        // Lookahead: If next item is large, prefer opening a new bin if residuals are tight
        // Refined threshold logic based on mean_residual pressure
        let lookahead_pressure = if next_item_size > 0 && (next_item_size as f64) > (mean_residual * 1.6) {
            1950.0
        } else {
            1050.0
        };
        score = base_cost + scale_factor + lookahead_pressure;
    } else {
        // Reward perfect or near-perfect fits aggressively
        if post_residual == 0 {
            score -= 9800.0 + (progress * 4500.0);
        } else if post_residual < (bin_capacity / 20) {
            score -= 6200.0 * (1.0 - progress * 0.2);
        }

        // Penalize blocking future items: scaled by scarcity of fitting bins
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let scarcity_penalty = if fitting_bins_count <= 2 { 9200.0 } else { 2800.0 };
            score += scarcity_penalty * (1.0 + progress.powf(0.6));
        }

        // Targeted residual control: force packing toward the current mean_residual
        // Adjusted target residual to be more aggressive in the final phase
        let target_residual = mean_residual * (0.55 + (progress * 0.35));
        let deviation = (target_residual - post).abs();
        score -= (deviation * 14.0) / (1.0 + (post / cap).sqrt());

        // Force compaction when few bins are available: critical bottleneck handler
        if fitting_bins_count <= 2 {
            score -= 24000.0 * (1.0 - progress * 0.1);
        }

        // Density pressure: penalize large remaining space with momentum
        score += post * (1.05 + progress.powf(1.1)) * 500.0;

        // Dead space penalty: focus on gaps that prevent future packing
        if post_residual < (bin_capacity / 10) && post_residual > 0 {
            score += 4800.0 * (1.0 - progress * 0.2);
        }

        // Lookahead optimization for next_item_size: match next item to current bin
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 3200.0 * (1.0 + progress * 0.2);
                if (post_residual - next_item_size) == 0 {
                    score -= 3000.0;
                }
            } else {
                score += 3500.0;
            }
        }

        // Entropy adjustment: minimize variance in residual space
        let entropy_penalty = (post - mean_residual).abs() * (1.5 - progress);
        score += entropy_penalty * 1400.0;

        // High density reward: prioritize closing bins that are nearly full
        if post < (cap * 0.1) && post > 0.0 {
            score -= 3200.0 * (1.0 - progress * 0.2);
        }
    }

    score
}
